INSERT IGNORE INTO page_section (page_key, section_key, area_code, title, body_html, sort_order) VALUES
  ('about.history', 'main', 'about', 'History: main text', '\r\n                   <p><strong>Katihar Engineering College</strong> is one of the seventeen engineering colleges established under the Department of Science and Technology, Govt. of Bihar. It was established in the year 2016 with the goal to foster technical skills in both applied and basic approaches. The establishment was laid as per the demand for technical education in our society today. The college started with three branches including Civil Engineering, Mechanical Engineering, and Computer Science Engineering with an intake of 60 students in each branch.</p>\r\n                   <p>After its establishment, the institution aims at setting high standards of education and excelling as per the demand of the current society. The institution not only aims at the pedantic way of learning but also to meet contemporary industrial requirements and to build human potential to become exemplary professionals.</p>\r\n               ', 10),
  ('about.principal', 'main', 'about', 'Principal''s Message: message and signature', '\r\n                               <p>Education comes from within, you get it by struggle, effort, and thought. <strong>We cannot always build the future for our students, but we can build our students for the future.</strong></p>\r\n                               <p>At KEC Katihar, we focus on grooming young minds as the pillar of advancement of a nation & hope of the future. We believe in humanity, discipline, punctuality, and regularity. Words visualize the ambition, and our aim is to educate the students to LEARN, not just STUDY.</p>\r\n                               <p>Hard work and discipline are the sure roads towards success. Therefore, our doctrine of student development is based on three Ds - Determination, Dedication, and Discipline so that they can excel in their respective fields. Our main job is not only to get them jobs but to facilitate them to provide jobs. Ergo, we strive to endeavor beyond the boundaries of mere books.</p>\r\n                               <p>So, it''s my pleasure to welcome you to KEC Katihar, an institute under the Department of Science and Technology, Government of Bihar. We ensure that the students prove themselves to be not only well-qualified engineers but also very responsible and ideal citizens of our country.</p>\r\n                               <hr class="my-4"/>\r\n                               <p>With Regards,<br/> <strong>Smt. Ranjana Kumari</strong><br/> Email: <a href="mailto:principalranjanakri84@gmail.com" class="text-blue-500 hover:underline">principalranjanakri84@gmail.com</a></p>\r\n                           ', 10),
  ('about.vision', 'vision', 'about', 'Vision & Mission: vision', '<ul class="list-disc pl-8 space-y-2">\r\n                        <li>To establish an exclusive profile as a premier global technical institute which nurtures proficient technical professionals and resources, and consequently, drives the economic and social development of the nation and region.\r\n                        </li>\r\n                        \r\n                    </ul>', 10),
  ('about.vision', 'mission', 'about', 'Vision & Mission: mission', '<ul class="list-disc pl-8 space-y-2">\r\n                        <li>To promote academic excellence in technical education with enhanced teaching-learning practices.</li>\r\n                        <li>To cultivate an atmosphere of research and lead in technological advancement through collaboration with industry and academia.</li>\r\n                        <li> To create ethically-sound, future leaders who lead the inclusive and sustainable development of the state, nation and society at large.</li>\r\n                    </ul>', 20),
  ('about.affiliation', 'main', 'about', 'Affiliation: text', '\r\n                           <p>\r\n                               The Institute is academically governed by <a id="ctl00_ContentPlaceHolder1_hl_aryabhatta" href="http://beu-bih.ac.in/" target="_blank" rel="noopener" class="text-blue-500 hover:underline">Bihar Engineering University, Patna</a> which is the degree awarding authority for the institute as B.Tech. is recognized by the A.I.C.T.E., New Delhi, and the Government of Bihar State.\r\n                           </p>\r\n                       ', 10);
INSERT IGNORE INTO site_setting (setting_key, setting_value, value_type, area_code, description) VALUES
  ('principal.faculty_id', '11', 'number', 'about', 'Faculty id of the principal (photo on the Principal''s Message page)');
